{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C12"],
      "claim": "A tocotrienol-rich palm oil fraction, a lipophilic isoprenoid chromanol structurally related to CoQ10's polar head and isoprenoid tail, has poor oral bioavailability in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Lycopene, a highly lipophilic C40 isoprenoid, showed only about 1.2% systemic availability after an oral dose dispersed in oil in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Phytoene, a non-conjugated C40 isoprenoid, was estimated to have 58.5 ± 18.9% absolute bioavailability in humans, indicating that some long-chain isoprenoids can be well absorbed.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C13"],
      "claim": "A 13C-lycopene compartmental study estimated 23.2% ± 8% bioavailability for all-trans lycopene in healthy humans, providing an upper-range carotenoid absorption estimate.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is ubiquinone-10 (CoQ10), a very high-molecular-weight, poorly water-soluble benzoquinone with a long isoprenoid tail. The most transferable experimental evidence—tocotrienol poor bioavailability and lycopene low systemic availability—supports low oral bioavailability. Phytoene and some lycopene compartmental estimates suggest that certain isoprenoids can be absorbed well, but CoQ10's larger size and poor dissolution make F ≥ 20% less likely.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for CoQ10 in humans is provided.",
    "Formulation and food-matrix effects are not controlled across the analog records.",
    "The distinction between true absorption and systemic plasma appearance is inconsistent across carotenoid records."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

